class Solution:
    def numWays(self, words, target):
        MOD = 10**9 + 7
        n = len(target)
        count = [0] * 26
        for word in words:
            for c in word:
                count[ord(c) - ord('a')] += 1

        dp = [0] * (n + 1)
        dp[0] = 1
        for i in range(1, n + 1):
            for j in range(26):
                if target[i - 1] == chr(j + ord('a')):
                    dp[i] += dp[i - 1] * count[j]
                count[j] -= 1
            dp[i] %= MOD

        return dp[n]
